True def transform(grid):
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next(value for value in counts if value != background)
    return [[foreground if value == background else 0 for value in row] for row in grid]
